#include <vector>

int findSecondLargest(std::vector<int> arr) {
    if (arr.size() < 2) return -1; // No valid second largest

    int left = 0;
    int right = arr.size() - 1;

    while (left != right) {
        auto pivotIndex = partition(arr, left, right);

        if (pivotIndex == arr.size() - 2) { // Found the second largest
            return arr[pivotIndex];
