}

int partition(std::vector<int>& arr, int left, int right) {
    std::swap(arr[left], arr[right]); // Move pivot to end
    int i = left;
    for (int j = left; j < right; ++j) {
        if (arr[j] <= arr[right]) {
            std::swap(arr[i], arr[j]);
            i++;
        }
    }
    std::swap(arr[i], arr[right]); // Place pivot at its correct position
    return i;
}

int main() {
    std::vector<int> arr = {3, 5, 2, 8, 6};
    std::cout << "The second largest number is: " << findSecondLargest(arr) << std::endl;
    return 0;
}
```

